  "web-logtop": { d: "Real-time ranking of any log field (IP, URL, user agent) with frequency per second.",
    r: "sudo apt install logtop",
    f: ["Source IP / requested URL.", "History size.", "Avoids pipeline delays."],
    x: "See live which IP + URL combination is hammering the server: typical of a bot attacking wp-login.php or a crawler." },
